solution.solution.js:
const LINE = /^(?<date>\d{4}-\d{2}-\d{2}) (?<time>\d{2}:\d{2}:\d{2}) \[(?<level>[a-z]+)\] (?<source>\w+): (?<message>.*)$/i;

function parseLog(text) {
  const entries = [];
  for (const line of text.split(/\r?\n/)) {
    const m = line.match(LINE);
    if (!m) continue;
    const { date, time, level, source, message } = m.groups;
    entries.push({ date, time, level: level.toUpperCase(), source, message: message.trim() });
  }
  return entries;
}

function countByLevel(entries) {
  const counts = {};
  for (const e of entries) counts[e.level] = (counts[e.level] ?? 0) + 1;
  return counts;
}

unitTests:
const LOG = "2026-11-20 14:03:12 [WARN] disk: 91% used\r\n2026-11-20 14:03:15 [ERROR] net: timeout after 30s\ngarbage line\n2026-11-20 14:04:00 [info] auth: user ada logged in  \n";

test("parses the valid lines", () => {
  const entries = parseLog(LOG);
  checkEq(entries.length, 3);
  checkEq(entries[0], { date: "2026-11-20", time: "14:03:12", level: "WARN", source: "disk", message: "91% used" });
  checkEq(entries[2].level, "INFO");
  checkEq(entries[2].message, "user ada logged in");
});

test("skips what does not fit", () => {
  checkEq(parseLog(""), []);
  checkEq(parseLog("2026-11-20 14:03 [WARN] disk: short time\n[WARN] x: no date"), []);
});

test("counts by level", () => {
  checkEq(countByLevel(parseLog(LOG)), { WARN: 1, ERROR: 1, INFO: 1 });
  checkEq(countByLevel([]), {});
});

